// schema/generate.mjs: the committed generated files, the rendered output and --check.
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  BATCH_STATUSES, LIMITS, OPEN_BATCH, RESULT_STATES, SIZES, SUBTASK_FIELDS, TERMINAL_RESULT,
} from '../lib/order-schema.mjs';
import {
  JS_OUTPUT, PY_OUTPUT, differences, limitConstant, loadSchema, renderJs, renderPython, writeGenerated,
} from '../../schema/generate.mjs';

const ROOT = fileURLToPath(new URL('../..', import.meta.url));
const GENERATOR = path.join(ROOT, 'schema', 'generate.mjs');
const order = JSON.parse(fs.readFileSync(path.join(ROOT, 'schema', 'order.json'), 'utf8'));
const limitConstants = Object.fromEntries(Object.entries(order.limits).map(([key, value]) => [limitConstant(key), value]));

function withTempDir(fn) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'order-schema-'));
  try {
    fn(dir);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

// The strings of one generated Python tuple or frozenset (one item per line).
function pythonStrings(text, name) {
  const block = text.match(new RegExp(`^${name} = (?:\\(|frozenset\\(\\[)\\n((?:    ".*",\\n)*)`, 'm'));
  assert.ok(block, `${name} is missing`);
  return block[1].trimEnd().split('\n').map((line) => JSON.parse(line.trim().slice(0, -1)));
}

function findPython() {
  for (const command of ['python', 'python3']) {
    if (spawnSync(command, ['--version'], { encoding: 'utf8' }).status === 0) return command;
  }
  return null;
}
const PYTHON = findPython();

// Loads the file directly so importing it does not pull in the foundry package.
const PY_DUMP = [
  'import importlib.util, json, sys',
  'spec = importlib.util.spec_from_file_location("order_schema", sys.argv[1])',
  'module = importlib.util.module_from_spec(spec)',
  'spec.loader.exec_module(module)',
  'values = {name: getattr(module, name) for name in module.__all__}',
  'print(json.dumps({k: sorted(v) if isinstance(v, frozenset) else v for k, v in values.items()}))',
].join('\n');

test('--check reports no difference on the committed files', () => {
  const run = spawnSync(process.execPath, [GENERATOR, '--check'], { encoding: 'utf8' });
  assert.equal(run.status, 0, run.stdout + run.stderr);
  assert.equal(run.stdout, '');
});

test('generated JS exports equal order.json', () => {
  assert.deepEqual(BATCH_STATUSES, order.batchStatuses);
  assert.deepEqual(RESULT_STATES, order.resultStates);
  assert.deepEqual([...TERMINAL_RESULT], order.terminalResults);
  assert.deepEqual([...OPEN_BATCH], order.openBatches);
  assert.deepEqual(SIZES, order.sizes);
  assert.deepEqual(SUBTASK_FIELDS, order.subtaskFields);
  assert.deepEqual(Object.entries(LIMITS), Object.entries(order.limits));
  assert.ok(Object.isFrozen(LIMITS));
});

test('the generated files start with the required header', () => {
  assert.equal(renderJs(order).split('\n')[0], '// GENERATED by schema/generate.mjs from schema/order.json. Do not edit.');
  assert.equal(renderPython(order).split('\n')[0], '# GENERATED by schema/generate.mjs from schema/order.json. Do not edit.');
});

test('generated Python text holds the values of order.json', () => {
  const text = renderPython(order);
  assert.deepEqual(pythonStrings(text, 'BATCH_STATUSES'), order.batchStatuses);
  assert.deepEqual(pythonStrings(text, 'RESULT_STATES'), order.resultStates);
  assert.deepEqual(pythonStrings(text, 'SIZES'), order.sizes);
  assert.deepEqual(pythonStrings(text, 'SUBTASK_FIELDS'), order.subtaskFields);
  assert.deepEqual(pythonStrings(text, 'TERMINAL_RESULT'), order.terminalResults);
  assert.deepEqual(pythonStrings(text, 'OPEN_BATCH'), order.openBatches);
  const constants = Object.fromEntries([...text.matchAll(/^(LIMIT_[A-Z_]+) = (\d+)$/gm)].map((m) => [m[1], Number(m[2])]));
  assert.deepEqual(constants, limitConstants);
  assert.equal(constants.LIMIT_ACCEPTANCE_ITEM, order.limits.acceptanceItem);
  assert.equal(constants.LIMIT_HELP_OPTIONS, order.limits.helpOptions);
  assert.equal(constants.LIMIT_BUILDER_ORDER, order.limits.builderOrder);
});

test('the committed Python module imports and equals order.json', { skip: !PYTHON && 'python is not installed' }, () => {
  const run = spawnSync(PYTHON, ['-B', '-c', PY_DUMP, path.join(ROOT, PY_OUTPUT)], { encoding: 'utf8' });
  assert.equal(run.status, 0, run.stderr);
  assert.deepEqual(JSON.parse(run.stdout), {
    BATCH_STATUSES: order.batchStatuses,
    RESULT_STATES: order.resultStates,
    SIZES: order.sizes,
    SUBTASK_FIELDS: order.subtaskFields,
    TERMINAL_RESULT: [...order.terminalResults].sort(),
    OPEN_BATCH: [...order.openBatches].sort(),
    LIMITS: order.limits,
    ...limitConstants,
  });
});

test('editing a copy of the JSON changes the rendered output', () => {
  withTempDir((dir) => {
    const copy = path.join(dir, 'order.json');
    fs.writeFileSync(copy, JSON.stringify({ ...order, limits: { ...order.limits, help: 1234 } }, null, 2));
    const edited = loadSchema(copy);
    assert.notEqual(renderJs(edited), renderJs(order));
    assert.notEqual(renderPython(edited), renderPython(order));
    assert.match(renderJs(edited), /^ {2}help: 1234,$/m);
    assert.match(renderPython(edited), /^LIMIT_HELP = 1234$/m);
  });
});

test('differences lists stale and missing files and ignores CRLF line endings', () => {
  withTempDir((root) => {
    writeGenerated(order, root);
    assert.deepEqual(differences(order, root), []);

    const python = path.join(root, PY_OUTPUT);
    fs.writeFileSync(python, fs.readFileSync(python, 'utf8').replace(/\n/g, '\r\n'));
    assert.deepEqual(differences(order, root), []);

    assert.deepEqual(differences({ ...order, sizes: [...order.sizes, 'XXL'] }, root), [JS_OUTPUT, PY_OUTPUT]);

    fs.rmSync(path.join(root, JS_OUTPUT));
    assert.deepEqual(differences(order, root), [JS_OUTPUT]);
  });
});

test('limits.help is 2000 and limits.builderOrder is 24000', () => {
  assert.equal(order.limits.help, 2000);
  assert.equal(order.limits.builderOrder, 24000);
  assert.equal(LIMITS.help, 2000);
  assert.equal(LIMITS.builderOrder, 24000);
});
